scwin.grd_Main_onrowindexchange = function(row, oldRow) {
	dlt_GridList2.clearFilter();
	var str = dlt_GridList.getCellData(row, "parentName");
	dlt_GridList2.setColumnFilter({
		type: 'row',
		colIndex: 'parentName',
		key: str,
		condition: 'and'
	});
};
scwin.trigger1_onclick = function(e) {
	var data = dlt_GridList2.getRealRowIndexArr();
	localStorage.setItem("log", data.length);
};
scwin.onpageload = function() {
	scwin.complete();
	localStorage.removeItem("log");
};
